package io.github.long0823.tclbondriver;
import android.content.*;import android.os.*;import android.net.Uri;import java.io.*;import java.lang.reflect.*;
/** Root-only, application-private JSON writer, using Android's shell provider API. */
public final class RootConfigMain {
 public static void main(String[] args)throws Exception{if(android.os.Process.myUid()!=0||args.length!=1)throw new SecurityException();File file=new File(args[0]);if(!file.getCanonicalPath().startsWith(new File("/data/user/0/io.github.long0823.tclbondriver/cache").getCanonicalPath()+"/")||file.length()>65536)throw new SecurityException();ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=new FileInputStream(file)){byte[] b=new byte[4096];int n;while((n=in.read(b))>0)bytes.write(b,0,n);}String json=bytes.toString("UTF-8");new org.json.JSONArray(json);Object manager=Class.forName("android.app.ActivityManager").getMethod("getService").invoke(null);Class<?> activity=Class.forName("android.app.IActivityManager");Binder token=new Binder();String authority="com.tcl.config.ConfigProvider";Object holder=activity.getMethod("getContentProviderExternal",String.class,int.class,IBinder.class,String.class).invoke(manager,authority,0,token,"TCLBonDriver");if(holder==null)throw new IOException("TCL policy provider missing");try{Object provider=holder.getClass().getField("provider").get(holder);ContentValues values=new ContentValues();values.put("config_content",json);int changed=(Integer)Class.forName("android.content.IContentProvider").getMethod("update",String.class,String.class,Uri.class,ContentValues.class,Bundle.class).invoke(provider,null,null,Uri.parse("content://"+authority+"/AppBootPolicy"),values,Bundle.EMPTY);System.out.println("Updated "+changed+" rows");if(changed!=1)throw new IOException("Policy update count mismatch");}finally{activity.getMethod("removeContentProviderExternalAsUser",String.class,IBinder.class,int.class).invoke(manager,authority,token,0);}}
}